        const next = journey[l.id].next;
        if (next) {
          const link = document.createElement("a");
          link.className = "button";
          link.href = `#lesson/${next}`;
          link.textContent = `Weiter: ${byId(next).title}`;
          $("#completionResult").append(document.createElement("br"), link);
          decorateIcons();
        }
